import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing } from '../remotionShim';
// --- Font Loader ---
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};

// --- Schema ---


export type PixarIntroProps = Record<string, any>;

// --- Components ---

const Lamp: React.FC<{ 
  color: string; 
  lookUp: number; 
  squash: number;
  bulbGlow?: number;
  tiltTowardCamera?: number;
  sideTilt?: number;
}> = ({ 
  color, 
  lookUp, 
  squash,
  bulbGlow = 0,
  tiltTowardCamera = 0,
  sideTilt = 0
}) => {
  const tiltProgress = Math.min(1, Math.max(0, tiltTowardCamera / -75));

  // Dynamic gradient center to map spherical shading smoothly from side view to front view
  const gradX = tiltProgress * 40;
  const gradY = 50 - (tiltProgress * 10);

  return (
    <div style={{ 
      position: 'relative', 
      width: 100, 
      height: 120,
      transformOrigin: 'bottom center',
      transform: `scale(${1 + squash}, ${1 - squash})`,
      transformStyle: 'preserve-3d'
    }}>
      {/* Base */}
      <div style={{
        position: 'absolute',
        bottom: 0,
        left: 20,
        width: 60,
        height: 20,
        background: color,
        borderRadius: '50% 50% 0 0',
        boxShadow: '0px 2px 5px rgba(0,0,0,0.3)'
      }} />
      
      {/* Arm */}
      <div style={{
        position: 'absolute',
        bottom: 15,
        left: 45,
        width: 10,
        height: 60,
        background: color,
        transform: `rotate(${interpolate(lookUp, [0, 1], [-15, 20])}deg)`, 
        transformOrigin: 'bottom center',
        borderRadius: 5,
      }} />

      {/* Head Group */}
      <div style={{
        position: 'absolute',
        bottom: 70,
        left: 30,
        width: 60,
        height: 50,
        transform: `rotate(${interpolate(lookUp, [0, 1], [30, -40])}deg) rotateY(${tiltTowardCamera}deg) rotateZ(${sideTilt}deg)`, 
        transformOrigin: '15px 40px',
        transition: 'none',
        transformStyle: 'preserve-3d'
      }}>
        {/* Cone */}
        <div style={{
            position: 'absolute',
            left: 0,
            top: 0,
            width: 0,
            height: 0,
            borderLeft: '25px solid transparent',
            borderRight: '25px solid transparent',
            borderBottom: `50px solid ${color}`,
            transform: 'rotate(-90deg)',
            filter: 'drop-shadow(2px 2px 2px rgba(0,0,0,0.2))'
        }} />
        
        {/* Bulb - Morphs from side view to a 3D volume front view */}
        <div style={{
            position: 'absolute',
            left: 50 - (tiltProgress * 20),
            top: 15 - (tiltProgress * 5),
            width: 15 + (tiltProgress * 15),
            height: 20 + (tiltProgress * 10),
            background: `radial-gradient(circle at ${gradX}% ${gradY}%, #ffffff 0%, #e0e0e0 40%, #999999 80%, #555555 100%)`,
            borderRadius: `${tiltProgress * 50}% 50% 50% ${tiltProgress * 50}%`,
            boxShadow: `
              inset -${5 * tiltProgress}px -${5 * tiltProgress}px ${10 * tiltProgress}px rgba(0,0,0,0.5),
              inset ${3 * tiltProgress}px ${3 * tiltProgress}px ${6 * tiltProgress}px rgba(255,255,255,0.9)
            `,
            display: 'flex',
            justifyContent: 'center',
            alignItems: 'center',
            transform: `translateZ(${2 + tiltProgress * 15}px)`,
            transformStyle: 'preserve-3d'
        }}>
            {/* Inner On State (3D Glow Volume) */}
            <div style={{
                position: 'absolute',
                width: '100%',
                height: '100%',
                borderRadius: 'inherit',
                opacity: bulbGlow,
                background: `radial-gradient(circle at ${gradX}% ${gradY}%, #ffffff 0%, #fff5aa 40%, #ffb300 80%, #cc5500 100%)`,
                boxShadow: `
                  inset -${5 * tiltProgress}px -${5 * tiltProgress}px ${10 * tiltProgress}px rgba(200,50,0,0.6),
                  inset ${3 * tiltProgress}px ${3 * tiltProgress}px ${6 * tiltProgress}px rgba(255,255,255,0.9),
                  0 0 ${30 * bulbGlow}px ${15 * bulbGlow}px rgba(255, 200, 0, ${bulbGlow * 0.8})
                `,
            }} />
            
            {/* Core Brightness Hotspot */}
            <div style={{
                position: 'absolute',
                width: '60%',
                height: '60%',
                background: 'rgba(255, 255, 255, 0.95)',
                borderRadius: '50%',
                opacity: bulbGlow,
                filter: 'blur(3px)',
                transform: 'translateZ(1px)' 
            }} />

            {/* Specular Glass Highlight */}
            <div style={{
                position: 'absolute',
                top: '15%',
                left: '15%',
                width: '40%',
                height: '30%',
                background: 'radial-gradient(ellipse at center, rgba(255,255,255,0.9) 0%, rgba(255,255,255,0) 70%)',
                borderRadius: '50%',
                transform: 'rotate(-30deg) translateZ(2px)',
                opacity: (0.5 + (bulbGlow * 0.5)) * tiltProgress, 
            }} />
        </div>

        {/* Volumetric Light Bloom - Counter rotates to always face the camera */}
        <div style={{
            position: 'absolute',
            left: -25, // Centers exactly on bulb (50 - 75)
            top: -50,  // Centers exactly on bulb (25 - 75)
            width: 150,
            height: 150,
            background: 'radial-gradient(circle, rgba(255, 240, 150, 0.6) 0%, rgba(255, 200, 50, 0) 60%)',
            opacity: bulbGlow,
            pointerEvents: 'none',
            transform: `rotateY(${-tiltTowardCamera}deg) scale(${1 + tiltProgress * 1.5}) translateZ(${10 + tiltProgress * 20}px)`,
        }} />
      </div>
    </div>
  );
};

// --- Main Component ---
const PixarIntro: React.FC<PixarIntroProps> = ({
  backgroundColor = "#000000",
  textColor = "#ffffff",
  lampColor = "#cccccc",
  transparentBackground = false,
  durationInSeconds = 10,
}) => {
  useFontLoader(["Playfair Display"]);
  const { fps, width, height } = useVideoConfig();
  const frame = useCurrentFrame();

  const bgColor = transparentBackground ? "transparent" : `radial-gradient(circle at center, #2a2a2a 0%, ${backgroundColor} 100%)`;
  
  // Calculate letter dimensions to allow precise landing
  const fontSize = width * 0.15;
  const letterHeight = fontSize * 1.15; 

  // --- Timing Constants (Frames) ---
  const F_START = 10;
  
  // Entry Hops
  const F_HOP1_S = 20;
  const F_HOP1_E = 40;
  const F_HOP2_S = 46; 
  const F_HOP2_E = 66; 
  
  // The Jump onto the "I"
  const F_JUMP_S = 80;
  const F_LAND_ON_I = 100;
  
  // The Bounce on the "I"
  const F_BOUNCE_S = 108;
  const F_BOUNCE_E = 123; 
  
  // The Crush
  const F_CRUSH_S = 130;
  const F_CRUSH_E = 145;
  const F_LOOK_UP = 160;

  // --- Ending Sequence Constants ---
  const F_FLICKER_S = 170;
  const F_FLICKER_E = 190;

  // --- Animation Logic ---

  // 1. Scene Fade In
  const opacity = interpolate(frame, [0, F_START], [0, 1], { extrapolateRight: "clamp" });

  // Stage Lighting Darkening Overlay (Focuses purely on lamp)
  const stageDarkening = interpolate(
    frame, 
    [F_FLICKER_S, F_FLICKER_E + 20], 
    [0, 0.9], 
    { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: Easing.inOut(Easing.ease) }
  );

  // 2. Lamp Position (X)
  const lampX = interpolate(frame, 
    [F_HOP1_S, F_HOP1_E, F_HOP2_S, F_HOP2_E, F_JUMP_S, F_LAND_ON_I],
    [width * 0.8, width * 0.65, width * 0.65, width * 0.50, width * 0.50, width * 0.36], 
    { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.bezier(0.42, 0, 0.58, 1) }
  );

  // 3. Lamp Position (Y)
  const hop1Y = interpolate(frame, [F_HOP1_S, (F_HOP1_S+F_HOP1_E)/2, F_HOP1_E], [0, -60, 0], {
    extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.quad
  });
  
  const hop2Y = interpolate(frame, [F_HOP2_S, (F_HOP2_S+F_HOP2_E)/2, F_HOP2_E], [0, -60, 0], {
    extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.quad
  });

  const jumpToI_Y = interpolate(frame, 
    [F_JUMP_S, (F_JUMP_S+F_LAND_ON_I)/2, F_LAND_ON_I], 
    [0, -letterHeight * 1.3, -letterHeight], 
    { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.bezier(0.5, 0, 0.5, 1) }
  );

  const bounceOnI_Y = interpolate(frame,
    [F_BOUNCE_S, (F_BOUNCE_S+F_BOUNCE_E)/2, F_BOUNCE_E],
    [0, -40, 0], 
    { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.quad
  });

  const rideDownY = interpolate(frame,
    [F_CRUSH_S, F_CRUSH_E],
    [0, letterHeight * 0.60],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.elastic(1) }
  );

  let currentLampY = 0;
  if (frame < F_JUMP_S) {
    currentLampY = hop1Y + hop2Y;
  } else {
    currentLampY = jumpToI_Y + bounceOnI_Y + rideDownY;
  }

  // 4. Lamp Squash & Stretch (Injected bobbing for look up/down)
  const squashValues = [
    [F_HOP1_S, 0], [F_HOP1_S + 5, 0.1], [F_HOP1_E - 2, -0.1], [F_HOP1_E, 0.15], [F_HOP1_E + 5, 0],
    [F_HOP2_S, 0], [F_HOP2_S + 5, 0.1], [F_HOP2_E - 2, -0.1], [F_HOP2_E, 0.15], [F_HOP2_E + 5, 0],
    [F_JUMP_S, -0.2], [F_JUMP_S + 5, 0.2], 
    [F_LAND_ON_I - 2, -0.1], [F_LAND_ON_I, 0.2], [F_LAND_ON_I + 5, 0],
    [F_BOUNCE_S, -0.05], [F_BOUNCE_S + 3, 0.05], [F_BOUNCE_E, 0.1], [F_BOUNCE_E + 4, 0],
    [F_CRUSH_S, -0.2], [F_CRUSH_E, 0.3], [F_CRUSH_E + 10, 0]
  ];
  
  const squash = interpolate(
    frame,
    squashValues.map(v => v[0] as number),
    squashValues.map(v => v[1] as number),
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // 5. Look Up Logic
  const lookUp = interpolate(frame, 
    [F_HOP2_E + 5, F_JUMP_S, F_LAND_ON_I, F_BOUNCE_S, F_CRUSH_E, F_LOOK_UP],
    [0, 1, 0, 1, 0, 1], 
    { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.inOut(Easing.ease) }
  );

  // 6. Letter 'I' Logic
  const iScaleY = interpolate(frame,
    [F_CRUSH_S, F_CRUSH_E],
    [1, 0.05],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.elastic(1) }
  );
  
  const iOpacity = interpolate(frame,
     [F_CRUSH_E, F_CRUSH_E + 5],
     [1, 0.8],
     { extrapolateLeft: "clamp", extrapolateRight: "clamp"}
  );

  // --- Ending Animators ---
  
  // Flicker logic with warm bloom
  const bulbGlow = interpolate(
    frame,
    [
      F_FLICKER_S, F_FLICKER_S + 2, 
      F_FLICKER_S + 4, F_FLICKER_S + 6, 
      F_FLICKER_S + 8, F_FLICKER_S + 12, 
      F_FLICKER_S + 14, F_FLICKER_E
    ],
    [
      0, 0.8,
      0.1, 1.0,
      0.2, 0.9,
      0.6, 1
    ],
    { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' }
  );

  // --- Styles ---
  const containerStyle: React.CSSProperties = {
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    width: "100%",
    height: "100%",
    background: bgColor,
    fontFamily: "Playfair Display",
    perspective: "1000px",
    overflow: "hidden"
  };

  const letterStyle: React.CSSProperties = {
    fontSize: fontSize,
    fontWeight: 700,
    color: textColor,
    textShadow: `0px 10px 20px rgba(0,0,0,0.5)`,
    position: 'relative',
    lineHeight: 1,
  };

  const lampScreenX = lampX; 
  const lampScreenY = (height * 0.55) + currentLampY; 

  return (
    <AbsoluteFill style={containerStyle}>
      <AbsoluteFill style={{ opacity }}>
        
        {/* Floor Reflection / Shadow Base */}
        <div style={{
          position: 'absolute',
          bottom: 0,
          width: '100%',
          height: '40%',
          background: `linear-gradient(to bottom, rgba(255,255,255,0.05), transparent)`,
          transformOrigin: 'top',
          transform: 'perspective(500px) rotateX(60deg)'
        }}/>

        {/* Text Container */}
        <div style={{
           position: 'absolute',
           left: 0,
           top: 0,
           width: '100%',
           height: '100%',
           display: 'flex',
           justifyContent: 'center',
           alignItems: 'center',
           paddingBottom: height * 0.1,
           zIndex: 10
        }}>
           <div style={{ display: 'flex', gap: 20 }}>
              <span style={letterStyle}>P</span>
              
              {/* The Crushed I */}
              <div style={{ position: 'relative', width: width * 0.04, display: 'flex', justifyContent: 'center' }}>
                 <span style={{ 
                    ...letterStyle, 
                    display: 'inline-block', 
                    transformOrigin: 'bottom center',
                    transform: `scaleY(${iScaleY})`,
                    opacity: iOpacity
                 }}>I</span>
                 
                 {/* Debris / Sparkle on crush */}
                 {frame > F_CRUSH_S && frame < F_CRUSH_E + 10 && (
                    <div style={{
                        position: 'absolute', bottom: 0, width: 40, height: 5, background: 'white', borderRadius: '50%',
                        opacity: interpolate(frame, [F_CRUSH_S, F_CRUSH_E], [0, 0.8])
                    }}/>
                 )}
              </div>

              <span style={letterStyle}>X</span>
              <span style={letterStyle}>A</span>
              <span style={letterStyle}>R</span>
           </div>
        </div>

        {/* Stage Darkening Overlay for Warm Stage Light Effect */}
        <div style={{
          position: 'absolute',
          top: 0,
          left: 0,
          width: '100%',
          height: '100%',
          background: '#000000',
          opacity: stageDarkening,
          zIndex: 15,
          pointerEvents: 'none',
        }} />

        {/* Lamp Layer */}
        <div style={{
          position: 'absolute',
          left: 0,
          top: 0,
          transform: `translate(${lampScreenX}px, ${lampScreenY}px)`,
          zIndex: 20,
          perspective: 800
        }}>
           <Lamp 
              color={lampColor} 
              lookUp={lookUp} 
              squash={squash}
              bulbGlow={bulbGlow}
           />
           
           {/* Dynamic Shadow for Lamp */}
           <div style={{
             position: 'absolute',
             bottom: 5,
             left: 20,
             width: 60,
             height: 10,
             background: 'rgba(0,0,0,0.4)',
             borderRadius: '50%',
             transform: `scale(${interpolate(currentLampY, [-200, 0], [1.5, 1], { extrapolateRight: 'clamp' })})`,
             opacity: interpolate(currentLampY, [-50, 0], [0.1, 0.5], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' }),
             filter: 'blur(4px)',
             zIndex: -1
           }} />
        </div>

      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default PixarIntro;